const { button, div, h2, input, p } = HTML;
let doReload = false;

export class CustomPresetsPrompt implements Prompt {
	private readonly _presetsInput: HTMLInputElement = input({ type: "text", value: localStorage.getItem("customPresets") || defaultCustomPresets });
	private readonly _copyButton: HTMLButtonElement = button({ class: "copyButton" }, "Copy Template");
	private readonly _cancelButton: HTMLButtonElement = button({ class: "cancelButton" });
	private readonly _okayButton: HTMLButtonElement = button({ class: "okayButton", style: "width:45%;" }, "Okay");
	private readonly _resetButton: HTMLButtonElement = button({ style: "height: auto; min-height: var(--button-size);" }, "Reset to defaults");

	public readonly container: HTMLDivElement = div({ class: "prompt noSelection", style: "width: 300px;" },
		h2("Custom Presets"),
        p({ style: "text-align: left; margin: 0;" },
            "Replace the text below with your custom preset data to load it. You can use shift + j to copy an instrument's JSON information. ",
			"The format for adding an instrument is \"[preset name] | [pitch or noise] | [JSON information];\". ",
			"You can also create your own instrument categories by following the existing format. ",
			"It is highly recommended to edit the preset data in a text editor rather than directly in the following prompt.",
        ),
        this._presetsInput,
		div(),
		p({ style: "text-align: left; margin: 0;" },
            "Click the button below to copy a formatted template:",
        ),
        this._copyButton,
        div({ style: "display: flex; flex-direction: row-reverse; justify-content: space-between;" },
            this._resetButton
        ),
        div({ style: "display: flex; flex-direction: row-reverse; justify-content: space-between;" },
            this._okayButton,
        ),
        this._cancelButton,
    );

    constructor(private _doc: SongDocument) {
        this._presetsInput.addEventListener("change", this._whenPresetsChanged);
        this._copyButton.addEventListener("click", this._whenCopyClicked);
        this._okayButton.addEventListener("click", this._close);
        this._cancelButton.addEventListener("click", this._close);
        this._resetButton.addEventListener("click", this._reset);
    }

    private _close = (): void => {
        this._doc.prompt = null;
        this._doc.undo();
		if (doReload) {
            // The prompt seems to get stuck if reloading is done too quickly.
            setTimeout(() => { window.location.reload(); }, 50);
        }
    }

    public cleanUp = (): void => {
        this._copyButton.removeEventListener("click", this._close);
        this._okayButton.removeEventListener("click", this._close);
        this._cancelButton.removeEventListener("click", this._close);
        this._resetButton.removeEventListener("click", this._reset);
    }

    private _reset = (): void => {
        window.localStorage.removeItem("customPresets");
        window.localStorage.removeItem("customPresetsCompiled");
		doReload = true;
        this._close();
    }

	private _whenCopyClicked = (): void => {
        this._copyTextToClipboard(defaultCustomPresets)
    }

	private _copyTextToClipboard(text: string): void {
        // Set as any to allow compilation without clipboard types (since, uh, I didn't write this bit and don't know the proper types library) -jummbus
        let nav: any;
        nav = navigator;

        if (nav.clipboard && nav.clipboard.writeText) {
            nav.clipboard.writeText(text).catch(() => {
                window.prompt("Copy to clipboard:", text);
            });
            return;
        }
        const textField: HTMLTextAreaElement = document.createElement("textarea");
        textField.textContent = text;
        document.body.appendChild(textField);
        textField.select();
        const succeeded: boolean = document.execCommand("copy");
        textField.remove();
        if (!succeeded) window.prompt("Copy this:", text);
    }

    private _whenPresetsChanged = (): void => {
        window.localStorage.setItem("customPresets", this._presetsInput.value);
		doReload = true;

		const splitCustomPresets: string[] = localStorage.getItem("customPresets")!.split(";");
		let categoryLocations: number[] = [];
		for (let i: number = 0; i < splitCustomPresets.length; i++) {
			if (!splitCustomPresets[i].includes("|")) {
				categoryLocations.push(i);
			}
		}
		let instruments = new Array(categoryLocations.length - 1);
		for (let i: number = 0; i < instruments.length; i++) {
			instruments[i] = [];
			if (categoryLocations[i] != splitCustomPresets.length) {
				for (let j: number = categoryLocations[i] + 1; j < categoryLocations[i + 1]; j++) {
					const splitInstrument = splitCustomPresets[j].split("|");
					let instrumentObject = { name: "", isNoise: false, settings: {} };
					instrumentObject.name = splitInstrument[0].trim();
					if (splitInstrument[1].trim() == "noise") instrumentObject.isNoise = true;
					instrumentObject.settings = JSON.parse(splitInstrument[2].trim());
					instruments[i].push(instrumentObject);
				}
			}
		}

		let customPresetCategories = [];

		let customInstruments = { name: "", presets: {} }
		customInstruments.name = "Custom Instruments";
		customInstruments.presets = <DictionaryArray<Preset>>toNameMap([
				{ name: TypePresets[InstrumentType.chip], customType: InstrumentType.chip },
				{ name: TypePresets[InstrumentType.fm], customType: InstrumentType.fm },
				{ name: TypePresets[InstrumentType.noise], customType: InstrumentType.noise },
				{ name: TypePresets[InstrumentType.spectrum], customType: InstrumentType.spectrum },
				{ name: TypePresets[InstrumentType.drumset], customType: InstrumentType.drumset },
				{ name: TypePresets[InstrumentType.harmonics], customType: InstrumentType.harmonics },
				{ name: TypePresets[InstrumentType.pwm], customType: InstrumentType.pwm },
				{ name: TypePresets[InstrumentType.pickedString], customType: InstrumentType.pickedString },
				{ name: TypePresets[InstrumentType.supersaw], customType: InstrumentType.supersaw },
				{ name: TypePresets[InstrumentType.customChipWave], customType: InstrumentType.customChipWave },
				{ name: TypePresets[InstrumentType.fm6op], customType: InstrumentType.fm6op },
			]);
		customPresetCategories.push(customInstruments);

		for (let i: number = 0; i < categoryLocations.length - 1; i++) {
			let presetCategory = { name: "", presets: {} }
			presetCategory.name = splitCustomPresets[categoryLocations[i]].trim();
			presetCategory.presets = <DictionaryArray<Preset>>toNameMap(instruments[i]);
			customPresetCategories.push(presetCategory);
		}
		console.table(customPresetCategories);

        window.localStorage.setItem("customPresetsCompiled", JSON.stringify(toNameMap(customPresetCategories)));
    }
}